import os,re,json,subprocess
from pathlib import Path
base=Path('/opt/telegram-robot-leads')
for rel in ('scripts/safe_runtime.py','scripts/organic_growth.py','scripts/leads_operational_report.py','config.py','README.md'):
 p=base/rel
 if not p.is_file():continue
 print('SOURCE',rel)
 for i,line in enumerate(p.read_text(errors='replace').splitlines(),1):
  if re.search(r'(state_path|state_file|STATE_FILE|STATE_PATH|persist|approved_user_ids_done|approved_join_requests_done|process.*groups|\.json|\.sqlite)',line,re.I) and not re.search(r'(api_hash|api_id|phone|secret|token|password)',line,re.I):
   print('SOURCELINE',i,line.strip()[:190])
   if i>300:break
for d in sorted((base/'.telegram-leads-release-backups').glob('*/manifest.json')):
 try: obj=json.loads(d.read_text())
 except Exception: continue
 print('RELEASE_MANIFEST',d.parent.name,'KEYS',sorted(obj))
 for key in ('previous_commit','target_commit','old_sha','new_sha','from_commit','to_commit','deployed_commit','git_sha','sha'):
  if key in obj and isinstance(obj[key],str):print('MANIFEST_VERSION',key,obj[key][:50])
for root in ('/var/lib','/srv','/root','/home/ubuntu','/opt'):
 p=Path(root)
 if not p.is_dir():continue
 try: dirs=list(p.iterdir())
 except OSError:continue
 for d in sorted(dirs,key=lambda v:v.name):
  if not d.is_dir() or d.is_symlink():continue
  if any(t in d.name.lower() for t in ('telegram','leads','robot')):
   print('RELATED_TOP_LEVEL',str(d))
   for q in (d/'data',d/'state',d/'backup',d/'backups'):
    if q.is_dir() and not q.is_symlink():
     try: files=list(q.iterdir())
     except OSError:continue
     print('STATE_DIR',str(q),'file_count',len(files),'candidate_count',sum(f.suffix.lower() in ('.json','.sqlite','.sqlite3','.db','.csv','.bak') for f in files if f.is_file()))
try:
 output=subprocess.run(['ps','-eo','user=,pid=,comm=,args='],capture_output=True,text=True,check=True,timeout=8).stdout
 for line in output.splitlines():
  if ('telegram-robot-leads' in line or 'telegram-leads' in line) and 'python3 -B -' not in line and 'capture_process' not in line and 'LEADS_STATE_DISCOVERY' not in line:
   xs=line.strip().split(None,3)
   if len(xs)>=3: print('LEADS_PROCESS','owner',xs[0],'pid',xs[1],'program',xs[2])
except Exception as e: print('PS_ERROR',type(e).__name__)
